files.content:
* { box-sizing: border-box; }
:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #26352f;
  background: #f5eee2;
}
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f5eee2;
  background-image: linear-gradient(#e9dece 1px, transparent 1px), linear-gradient(90deg, #e9dece 1px, transparent 1px);
  background-size: 24px 24px;
}
.converter {
  width: min(100%, 520px);
  padding: clamp(24px, 7vw, 40px);
  background: #fffdf8;
  border: 3px solid #26352f;
  border-radius: 8px;
  box-shadow: 8px 8px 0 #26352f;
}
.pixel-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  margin-bottom: 20px;
  border: 2px solid #26352f;
  background: #e9a65a;
  font-size: 32px;
  line-height: 1;
}
.eyebrow { margin: 0 0 6px; color: #52725f; font-size: 0.875rem; font-weight: 800; letter-spacing: 0.12em; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.75rem); line-height: 1.1; }
.intro { margin: 10px 0 28px; color: #56645c; }
.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.field { display: grid; gap: 8px; }
label { font-weight: 700; }
input, select {
  width: 100%;
  min-height: 50px;
  padding: 10px 12px;
  border: 2px solid #26352f;
  border-radius: 4px;
  background: #fffdf8;
  color: #26352f;
  font: inherit;
}
input:hover, select:hover { border-color: #52725f; }
input:focus-visible, select:focus-visible { outline: 3px solid #e9a65a; outline-offset: 3px; }
input:active, select:active { background: #f5eee2; }
.hint { margin: 10px 0 24px; color: #56645c; font-size: 0.9rem; }
.results { padding: 20px; background: #e7efe8; border: 2px solid #52725f; border-radius: 4px; }
h2 { margin: 0 0 14px; font-size: 1.125rem; }
#results-list { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; }
#results-list li { display: flex; justify-content: space-between; gap: 16px; padding-bottom: 8px; border-bottom: 1px solid #c3d2c6; }
#results-list li:last-child { padding-bottom: 0; border: 0; }
.result-value { font-weight: 800; font-variant-numeric: tabular-nums; }
.empty { color: #56645c; }
.ratio { margin: 20px 0 0; color: #56645c; font-size: 0.875rem; text-align: center; }
@media (max-width: 420px) {
  .fields { grid-template-columns: 1fr; gap: 14px; }
  .converter { box-shadow: 5px 5px 0 #26352f; }
}

const units = [
  { key: 'cups', label: 'Cups', short: 'cups', millilitres: 240 },
  { key: 'tablespoons', label: 'Tablespoons', short: 'tbsp', millilitres: 15 },
  { key: 'teaspoons', label: 'Teaspoons', short: 'tsp', millilitres: 5 },
  { key: 'millilitres', label: 'Millilitres', short: 'ml', millilitres: 1 }
];

const amountInput = document.querySelector('#amount');
const unitSelect = document.querySelector('#unit');
const resultsList = document.querySelector('#results-list');

function renderResults() {
  const amount = Number(amountInput.value);
  const source = units.find((unit) => unit.key === unitSelect.value);
  resultsList.replaceChildren();

  if (amountInput.value.trim() === '' || !Number.isFinite(amount) || amount < 0) {
    const message = document.createElement('li');
    message.className = 'empty';
    message.textContent = 'Enter a valid amount to see conversions.';
    resultsList.append(message);
    return;
  }

  const millilitres = amount * source.millilitres;
  units.filter((unit) => unit.key !== source.key).forEach((unit) => {
    const row = document.createElement('li');
    const label = document.createElement('span');
    const value = document.createElement('span');
    label.textContent = unit.label;
    value.className = 'result-value';
    value.textContent = `${(millilitres / unit.millilitres).toFixed(1)} ${unit.short}`;
    row.append(label, value);
    resultsList.append(row);
  });
}

amountInput.addEventListener('input', renderResults);
unitSelect.addEventListener('change', renderResults);
renderResults();
